insert into public.claims (id, position, where_text, claim, found, action)
select id, position, where_text, claim, found, action from jsonb_populate_recordset(null::public.claims, $j$[{"id":"A1","position":1,"where_text":"Ch.1 principle 2 ('859.6M tokens/day', '~190K per wake'); Ch.4 intro; task GF-T05-119; swarm lab ('~190K saved')","claim":"Paperclip #3401: 859.6M tokens/day, ~190K context tokens per wake","found":"The issue exists (open, 2026-04-11, 'Heartbeat is architecturally heavyweight'). The numbers come from a later comment (2026-08-28): 859.6M context tokens and 7.04M output tokens over an 8-day window for one agent, and an idle heartbeat is roughly ten turns each re-reading a ~190K prefix. So it is not per day, and 190K is per turn, not per wake.","action":"Reword to the source's figures, or cite them as 'one agent, 8 days'."},{"id":"A2","position":2,"where_text":"Prompt 11 (why-needed text, deliverable 2)","claim":"mmdr#112 prevents malformed Mermaid diagrams from hanging the daemon","found":"1jehuang/mermaid-rs-renderer#112 exists but is a rendering-accuracy report (CJK text clipping, architecture-beta ports), closed 2026-07-01. No hang is described.","action":"Remove the issue reference or describe the real reason for the 200 ms watchdog."},{"id":"A3","position":3,"where_text":"Pack 02, SPIKE-02","claim":"Lightpanda <45 MB RSS","found":"The project README (AGPL-3.0) reports 123 MB peak for 100 pages (vs 2 GB for headless Chrome). No 45 MB figure is claimed. SPIKE-02's gate (<50 MB on a 100-page crawl) is below the project's own number.","action":"Mark as a V20 target, or adjust the gate."},{"id":"A4","position":4,"where_text":"Pack 10","claim":"ghidra-mcp v7.0.0 (--lazy)","found":"bethington/ghidra-mcp has only 7.0.0-rc.1 to rc.3 (rc.3 on 14 Oct). Latest stable is 6.0.0 (25 Jul). No release note mentions lazy loading (one aggregator page does).","action":"Pin to a real version or say '7.0.0 release candidate'."},{"id":"A5","position":5,"where_text":"Crate forge-protocols; Prompt 04 deliverable 3","claim":"a2a-rust >= 0.14.1 fixing GHSA-hr9h-6jvf-wvg6","found":"The crate named a2a-rust has only 0.1.0. A crate a2a-protocol-types has 0.14.1. The advisory URL returned 404 (could be private or mistyped). The A2A protocol itself is at v1.0.1.","action":"Confirm the intended crate name and the advisory id."},{"id":"A6","position":6,"where_text":"forge-protocols, Prompt 04","claim":"fixing rmcp#1030 / #1283","found":"Both exist. #1030 (unbounded stdio line buffer) closed 2026-10-14 via PR #1049. #1283 (client accepts a response with both result and error, reported against rmcp 3.4.0) closed 2026-10-14 via PR #1287. rmcp 3.5.1 (2026-10-05) predates both fixes.","action":"Keep, but note the upstream fixes arrive in a release after 3.5.1."},{"id":"A7","position":7,"where_text":"Prompt 06, Pack 24","claim":"AgentShield 268 rules","found":"README says 268 rules across 15 modules but its own summary table totals 102. runtimeConfidence is real; template-example is 0.25x (matches). '1.0x active-runtime' is not stated literally (it says full weight).","action":"Say 'README claims 268 rules (its table lists 102)'."},{"id":"A8","position":8,"where_text":"forge-pty, Prompt 07","claim":"OSC 7501 (revision 0.2)","found":"OSC 7501 (Program Status Protocol) is real: Bubble Tea v2.1.0 (2026-10-08) added it, and Crush v0.98.0 is titled 'Rex, OSC 7501...'. No 'revision 0.2' was found.","action":"Confirm the revision number from the spec text."},{"id":"A9","position":9,"where_text":"forge-cu; Prompt 05 (why-needed)","claim":"cua#4906 1.2 s Windows root walks","found":"The issue exists (open): list_windows takes about 1.2 s per call, constant for 1 or 14 windows; the cause is not identified (UIA is only one guess).","action":"Reword to 'list_windows takes ~1.2 s'."},{"id":"A10","position":10,"where_text":"Ch.5 intro ('100% free forever'), agent-junie-lite-03 ('$0/free workhorse cost'), Confirm-07","claim":"Junie Lite is free","found":"JetBrains post (2026-10-02): free, 'virtually unlimited', runs Qwen 3.6 27B on JetBrains infrastructure, but the footnote says the offer is valid until 31 Dec 2026 and models may change.","action":"Add the end date, or avoid 'free forever' for Junie Lite."},{"id":"A11","position":11,"where_text":"forge-types","claim":"jcode#1828 threads deadlocked in competitor audits","found":"1jehuang/jcode#1828 exists (open, 2026-10-14): an ABBA deadlock in 'cargo test jcode-tui --lib' between a render lock and an env lock. A test-suite deadlock, not a production report.","action":"Say 'test-suite deadlock'."},{"id":"A12","position":12,"where_text":"Prompt 10 deliverable 3","claim":"goose#5253 (fixing) a 15s compaction watchdog","found":"Issue 'Summarize fails after 10mins' (closed 2025-10-20): a ~10-minute hard cap on summarize/compaction; the reporter asked for a configurable LLM timeout. The repo is now aaif-goose/goose. Related, not identical.","action":"Reword as 'related to'."},{"id":"A13","position":13,"where_text":"Prompt 04 deliverable 2","claim":"copilot-cli#4113 5-session standby recycling","found":"Issue 'ACP mode does not implement session/close' (closed 2026-07-31): resources stay until the shared process dies. Related, not about recycling.","action":"Reword."},{"id":"D1","position":14,"where_text":"'14 crates' wording","claim":"14 crates","found":"The registry has 14 entries = 12 under crates/ + 2 under bins/, and the last bins/ entry covers three binaries (so 12 crates + 4 binaries).","action":"Decide the wording."},{"id":"D2","position":15,"where_text":"'Six-target OS parity'","claim":"Six targets","found":"The matrix has 5 columns (Mint X11, Mint Wayland, Ubuntu Wayland, Windows x64, macOS). Windows 11 ARM64 is named in the text but has no column.","action":"Add the column or say five targets."},{"id":"D3","position":16,"where_text":"Crate badges","claim":"VERIFIED_PRIMARY_SOURCE on 13 of 14 crates","found":"The checks above do not support this for every claim.","action":"Use a label such as 'SPEC TARGET' unless a source is attached."},{"id":"D4","position":17,"where_text":"Patches F.1 to F.6; crate code blocks","claim":"'Verbatim' patches and code","found":"The patches are one-line stubs, and most crate code blocks are comment excerpts.","action":"Say 'excerpt', or supply the full text."},{"id":"D5","position":18,"where_text":"Anti-bloat table; '1.4 GB / 400 MB' savings","claim":"Savings figures","found":"No computed basis exists in the data.","action":"Add a basis or label them as estimates."}]$j$::jsonb);
